// Lightweight Pixel Font Engine to draw numbers directly onto the video feed
void drawDigit(uint8_t* buf, int buf_w, int x, int y, int digit, int scale) {
    const uint8_t font[10][5] = {
        {0x7, 0x5, 0x5, 0x5, 0x7}, // 0
        {0x2, 0x6, 0x2, 0x2, 0x7}, // 1
        {0x7, 0x1, 0x7, 0x4, 0x7}, // 2
        {0x7, 0x1, 0x7, 0x1, 0x7}, // 3
        {0x5, 0x5, 0x7, 0x1, 0x1}, // 4
        {0x7, 0x4, 0x7, 0x1, 0x7}, // 5
        {0x7, 0x4, 0x7, 0x5, 0x7}, // 6
        {0x7, 0x1, 0x1, 0x1, 0x1}, // 7
        {0x7, 0x5, 0x7, 0x5, 0x7}, // 8
        {0x7, 0x5, 0x7, 0x1, 0x7}  // 9
    };
    for(int row=0; row<5; row++) {
        for(int col=0; col<3; col++) {
            if(font[digit][row] & (1 << (2-col))) {
                // Scale up the pixel block
                for(int dy=0; dy<scale; dy++) {
                    for(int dx=0; dx<scale; dx++) {
                        buf[(y + row*scale + dy)*buf_w + (x + col*scale + dx)] = 255; // Draw White
                    }
                }
            }
        }
    }
}

void drawNumber(uint8_t* buf, int buf_w, int x, int y, int num, int scale) {
    String s = String(num);
    for(int i=0; i<s.length(); i++) {
        drawDigit(buf, buf_w, x + i*(4*scale), y, s.charAt(i) - '0', scale);
    }
}
```

