    if (right_speed > 0 && right_speed < MIN_ACTIVE_SPEED) {
        int adjustment = (right_speed <= midpoint) ? -right_speed : (MIN_ACTIVE_SPEED - right_speed);
        right_speed += adjustment;
        left_speed += adjustment; // Preserve differential
